from __future__ import annotations

import os
import sys
from pathlib import Path
from typing import Dict, Optional

try:
    # Python 3.8+: importlib.metadata in stdlib
    from importlib.metadata import version as pkg_version, PackageNotFoundError  # type: ignore
except Exception:  # pragma: no cover - very old Python fallback
    pkg_version = None  # type: ignore
    class PackageNotFoundError(Exception):
        ...


def _read_text_if_exists(path: Path) -> Optional[str]:
    try:
        if path.is_file():
            return path.read_text(encoding="utf-8").strip() or None
    except Exception:
        return None
    return None


def _coalesce(*values: Optional[str]) -> Optional[str]:
    for v in values:
        if v is not None and str(v).strip():
            return str(v).strip()
    return None


def _normalize_iso8601(value: Optional[str]) -> Optional[str]:
    if not value:
        return None
    v = value.strip()
    # Accept common build date formats and normalize trivial cases
    # If it already ends with 'Z' or contains timezone, keep as-is.
    if v.endswith("Z") or ("+" in v) or ("-" in v[10:]):
        return v
    # If it's a date-only (YYYY-MM-DD), promote to midnight Z
    if len(v) == 10 and v[4] == "-" and v[7] == "-":
        return f"{v}T00:00:00Z"
    # If it's a datetime without TZ, append Z
    if "T" in v and "Z" not in v and "+" not in v and "-" not in v[10:]:
        return f"{v}Z"
    return v


def _detect_version_from_files() -> Optional[str]:
    # Try repo root VERSION then module-local VERSION
    candidates = [
        Path.cwd() / "VERSION",
        Path(__file__).resolve().parent / "VERSION",
    ]
    for p in candidates:
        txt = _read_text_if_exists(p)
        if txt:
            return txt
    return None


def _detect_pkg_version(pkg_name: Optional[str]) -> Optional[str]:
    if not pkg_name or pkg_version is None:
        return None
    try:
        return pkg_version(pkg_name)
    except PackageNotFoundError:
        return None
    except Exception:
        return None


def version_info(service_name: Optional[str] = None) -> Dict[str, Optional[str]]:
    """
    Return version/build metadata for the service as a dict.

    Resolution order for version:
    1) ENV: VERSION
    2) VERSION file (repo root or core/VERSION)
    3) importlib.metadata for service/package name

    Additional fields from ENV when available: GIT_SHA, BUILD_DATE, SERVICE_NAME.
    """
    env = os.environ

    name = _coalesce(service_name, env.get("SERVICE_NAME")) or "service"

    ver = _coalesce(
        env.get("VERSION"),
        _detect_version_from_files(),
        _detect_pkg_version(name),
    ) or "unknown"

    git_sha = _coalesce(env.get("GIT_SHA"), env.get("COMMIT_SHA"))
    build_date = _normalize_iso8601(_coalesce(env.get("BUILD_DATE"), env.get("BUILD_TIMESTAMP")))

    py_ver = f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}"

    return {
        "name": name,
        "version": ver,
        "git_sha": git_sha,
        "build_date": build_date,
        "python_version": py_ver,
    }


__all__ = ["version_info"]
